#!/usr/bin/env bash
# SPDX-License-Identifier: Apache-2.0
# Copyright (c) 2026 Leoon-X
#
# Regenerates the Go code for the protocol in proto/ -> proto/gen/go.
# The Java code is generated by Gradle at build time and is not committed.
#
# Requires protoc, protoc-gen-go and protoc-gen-go-grpc on PATH.
set -euo pipefail

root="$(cd "$(dirname "$0")/.." && pwd)"
cd "$root/proto"
rm -rf gen/go
mkdir -p gen/go
protoc \
  --proto_path=. \
  --go_out=gen/go --go_opt=module=github.com/Leoon-X/leonsdb-connector/proto/gen/go \
  --go-grpc_out=gen/go --go-grpc_opt=module=github.com/Leoon-X/leonsdb-connector/proto/gen/go \
  $(find leonsdb -name '*.proto' | sort)
echo "generated: $(find gen/go -name '*.go' | wc -l | tr -d ' ') files"
